const mem = await tools.memory({ command: "view", path: "/memories" }).catch(e => ({ output: "memerr: " + e.message }));

const draft = String.raw`
\section{Setup}
Let $K \subset \mathbb{R}^n$ be compact and $f\colon K \to \mathbb{R}$ continuous.
\section{Main bound}
We claim $\sup_K |f| \le 1$. The proof is omitted.
\section{Discussion}
The bound is sharp for constant functions.
`;

// split into sections
const parts = draft.split(/\\section\{/).filter(s => s.trim());
const sections = {};
for (const p of parts) {
  const i = p.indexOf("}");
  sections[p.slice(0, i)] = p.slice(i + 1).trim();
}

const mb = sections["Main bound"] || "";

// what does Setup actually grant?
const setupHyps = {
  K_compact: /K \$?\\subset\$? .*compact|compact/.test(sections["Setup"]),
  f_continuous: /continuous/.test(sections["Setup"]),
  bound_on_f: /(\|f\|.*\\le|\\sup.*\\le|\|f\(x\)\|.*\\le).*/.test(sections["Setup"]),
  normalization: /(normali[sz]ed|unit ball|\|\|f\|\|_?\\?infty \\le 1|bounded by 1)/i.test(sections["Setup"]),
};

// does Main bound contain any proof content?
const proofMarkers = ["proof", "since", "because", "by ", "follows", "therefore", "hence", "\\qed", "theorem", "lemma", "proposition"];
const proofSignals = proofMarkers.filter(m => mb.toLowerCase().includes(m));
const saysOmitted = /proof is omitted/i.test(mb);
const wordsAfterClaim = mb.replace(/We claim[\s\S]*?\./, "").trim();

// counterexample: any constant c > 1 on any nonempty compact K
const K = [0]; // compact in R
const cs = [1, 1.5, 2, 100];
const rows = cs.map(c => ({ c, supAbsF: Math.max(...K.map(x => Math.abs(c * x + c))) }));
// f(x) = c constant on K={0}: f(0)=c
const constRows = cs.map(c => ({ c, f: `f ≡ ${c}`, sup: c, satisfiesSetup: true, satisfiesClaim: c <= 1 }));

// scaling argument: if any g with sup|g|=M>0 exists, c*g breaks it for c>1
const scaling = { closed_under_scaling: true, note: "K compact, f continuous => c*f compact-continuous for any c; sup|c f| = |c| sup|f|" };

return {
  sections: Object.keys(sections),
  mainBoundText: mb,
  setupHyps,
  mainBoundStructure: { proofSignals, saysOmitted, residualAfterClaim: wordsAfterClaim },
  counterexample: constRows,
  scaling,
  memory: mem.output ?? mem,
};

